import React, { useEffect, useRef, useState } from "react";
import AddIcon from "@mui/icons-material/Add";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import { uploadImage } from "../../services/utility";
import { useLocation, useNavigate } from "react-router-dom";
import { ReactComponent as DeleteIcon } from "../../assets/products/sub_categories/delete_icon.svg";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import { setProductVarient } from "../../redux/reducer/ProductVarientsReducer";
import { ReactComponent as BackButton } from "../../assets/products/add_product/backButton.svg";

export default function AddProductVarients() {
  const productVarientData = useSelector(
    (state) => state?.ProductVarients?.productVarient
  );
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [formData, setFormData] = useState([]);

  useEffect(() => {
    setFormData(productVarientData);
  }, [productVarientData]);

  const handleInputChange = (e, index) => {
    const { name, value } = e?.target;
    let data = [...formData];
    let updatedItem = { ...data[index] };
    updatedItem[name] = value;
    data[index] = updatedItem;
    setFormData(data);
  };

  const handleFlavourInputChange = (e, parentIndex, index) => {
    const { value } = e?.target;
    let data = [...formData];
    let updatedItem = { ...data[parentIndex] };
    let updatedFlavors = [...updatedItem["flavor"]];
    updatedFlavors[index] = value;
    updatedItem["flavor"] = updatedFlavors;
    data[parentIndex] = updatedItem;
    setFormData(data);
  };

  return (
    <div className="add_product_varients">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Edit Product Variants</h3>
      </div>
      <div className="add_product_varients__content">
        {/* <div className="add_product_varients__content__new_product_with_upload">
          <div
            className="add_product_varients__content__new_product_with_upload__upload_logo"
            onClick={() => newProductRef?.current?.click()}
          >
            <FileUploadIcon />
            <span>Upload Product image</span>
          </div>
          <input
            type="file"
            style={{ display: "none" }}
            ref={newProductRef}
            onChange={async (e) => {
              await uploadImage(e)
                .then((res) => {
                  let data = { ...formData };
                  data["images"].push(res?.url);
                  setFormData(data);
                })
                .catch((err) => {
                  console.log(err);
                });
            }}
          />

          {formData?.images?.map((data, index) => {
            return (
              <div
                className="add_product_varients__content__new_product_with_upload__uploaded_image"
                key={`add_product_banner_${index}`}
              >
                <img src={data} alt="whey protein" />
              </div>
            );
          })}
        </div> */}

        {formData?.map((item, index) => {
          return (
            <>
              <div className="add_product_varients__content__items" key={index}>
                <div className="add_product_varients__content__items__item_desc">
                  <label htmlFor="units">
                    Weight or units
                    <br />
                    <span>(for e.g. 1kg or 60 tablets)</span>
                  </label>
                  <input
                    type="text"
                    id="units"
                    name="units"
                    placeholder="Enter here"
                    value={item?.units}
                    onChange={(e) => handleInputChange(e, index)}
                  />
                </div>
                <div className="add_product_varients__content__items__item_desc">
                  <label htmlFor="stock">Available Stock</label>
                  <input
                    type="text"
                    id="stock"
                    name="stock"
                    placeholder="Enter here"
                    value={item?.stock}
                    onChange={(e) => handleInputChange(e, index)}
                  />
                </div>
                <div className="add_product_varients__content__items__item_desc">
                  <label htmlFor="date">Expiry date</label>
                  <input
                    type="datetime-local"
                    id="date"
                    name="date"
                    placeholder="Enter here"
                    value={item?.date}
                    min={new Date().toISOString().slice(0, 16)}
                    onChange={(e) => {
                      handleInputChange(e, index);
                    }}
                  />
                </div>
                <div className="add_product_varients__content__items__item_desc">
                  <label htmlFor="mrp">MRP</label>
                  <input
                    type="text"
                    id="mrp"
                    name="mrp"
                    placeholder="Enter here"
                    value={item?.mrp}
                    onChange={(e) => handleInputChange(e, index)}
                  />
                </div>
                <div className="add_product_varients__content__items__item_desc">
                  <label htmlFor="sellingPrice">Selling Price</label>
                  <input
                    type="text"
                    id="sellingPrice"
                    name="sellingPrice"
                    placeholder="Enter here"
                    value={item?.sellingPrice}
                    onChange={(e) => handleInputChange(e, index)}
                  />
                </div>
                <div className="add_product_varients__content__items__item_desc">
                  <label htmlFor="premiumPrice">Premium Price</label>
                  <input
                    type="text"
                    id="premiumPrice"
                    name="premiumPrice"
                    placeholder="Enter here"
                    value={item?.premiumPrice}
                    onChange={(e) => handleInputChange(e, index)}
                  />
                </div>
                {item?.flavor?.map((flav, ind) => {
                  return (
                    <div className="add_product_varients__content__items__item_desc">
                      <label htmlFor="flavor">
                        Flavor
                        {item?.flavor?.length > 1 && (
                          <DeleteIcon
                            onClick={() => {
                              let data = [...formData];
                              let updatedItem = { ...data[index] };
                              updatedItem["flavor"]?.splice(ind, 1);
                              data[index] = updatedItem;
                              setFormData(data);
                            }}
                          />
                        )}
                      </label>
                      <input
                        type="text"
                        id="flavor"
                        name="flavor"
                        placeholder="Enter here"
                        value={flav}
                        onChange={(e) =>
                          handleFlavourInputChange(e, index, ind)
                        }
                      />
                    </div>
                  );
                })}
                <>
                  <button
                    className="button-red"
                    onClick={() => {
                      let data = [...formData];
                      let updatedItem = { ...data[index] };
                      updatedItem["flavor"] = [...updatedItem["flavor"], ""];
                      data[index] = updatedItem;
                      setFormData(data);
                    }}
                  >
                    Add Flavor
                  </button>

                  <button
                    className="button-red"
                    onClick={() => {
                      let data = [...formData];
                      data = data?.filter((val) => {
                        return val?.id != item?.id;
                      });
                      setFormData(data);
                    }}
                  >
                    Delete
                  </button>
                </>
              </div>
              <hr />
            </>
          );
        })}

        <button
          className="button-border-red"
          onClick={() =>
            setFormData((prev) => {
              return [
                ...prev,
                {
                  id: formData[formData.length - 1]?.id + 1,
                  mrp: "",
                  units: "",
                  sellingPrice: "",
                  premiumPrice: "",
                  date: "",
                  stock: "",
                  flavor: [""],
                },
              ];
            })
          }
        >
          <AddIcon /> Add more
        </button>
        <div className="add_product_varients__content__footer">
          <div
            className="add_product_varients__content__footer__back"
            onClick={() => navigate(-1)}
          >
            <BackButton className="add_product_varients__content__footer__back__svg" />{" "}
            Back
          </div>
          <button
            className="button-red"
            onClick={() => {
              dispatch(setProductVarient(formData));
              navigate(-1);
            }}
          >
            Save and Continue
          </button>
        </div>
      </div>
    </div>
  );
}
